CREATE OR REPLACE FORCE VIEW ORDONNERPAYEMENT_CREE AS SELECT * FROM ORDONNERPAYEMENT_LIBETAT WHERE etat = 1;
CREATE OR REPLACE FORCE VIEW OrdonnerPayement_Vise AS SELECT * FROM ORDONNERPAYEMENT_LIBETAT WHERE etat = 11;
CREATE OR REPLACE FORCE VIEW OrdonnerPayement_Annule AS SELECT * FROM ORDONNERPAYEMENT_LIBETAT WHERE etat = 0;